-- Generated by scripts/richmd-project — do not hand-edit.
-- Document-shell hook (richmd#25 / ADR-0023): the 4th consumer contract.
-- Renders the masthead (eyebrow, lede) and colophon (footer) from the
-- page-identity frontmatter design_doc.frontmatter_keys declares; each
-- region preserves the value's inline markup (links, bold) by reading the
-- raw doc.meta metavalue, never stringifying. The masthead region also
-- prepends the framework's semantic-look overlay as a projected <style>
-- block (ADR-0024) — richmd owns the base look, the framework the semantic
-- look. Structure is richmd-* region elements; richmd owns the base look.
local function meta_to_inlines(v)
  if v == nil then return nil end
  if type(v) == "string" then
    if v == "" then return nil end
    return pandoc.Inlines({ pandoc.Str(v) })
  end
  if type(v) == "table" then
    local inlines = {}
    for _, el in ipairs(v) do table.insert(inlines, el) end
    if #inlines == 0 then return nil end
    return pandoc.Inlines(inlines)
  end
  return nil
end

